{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Entecavir, the closest structural analogue sharing the guanine carbocyclic nucleoside core, has 100% absolute oral bioavailability in humans, strongly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Cladribine, a halogenated purine nucleoside, showed 55% absolute oral bioavailability in patients, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Fludarabine phosphate immediate-release tablets gave approximately 55% absolute oral bioavailability in patients, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Clofarabine had an oral bioavailability of 57.5% in patients, supporting high F for this nucleoside analogue class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Didanosine under fasting conditions had a median F of 0.28, above the 20% threshold, indicating that even less bioavailable nucleoside analogues exceed the threshold when fasted.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "2FddC oral solutions gave a mean absolute bioavailability of about 50% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a guanine carbocyclic nucleoside analogue. The closest analogue entecavir has 100% human oral bioavailability, and other nucleoside analogues (cladribine, fludarabine, clofarabine, 2FddC) have F values of 35-70%. Even acid-labile didanosine exceeds 20% under fasting conditions. Therefore the query is predicted high for the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the exact query molecule; prediction relies on close analogues.",
    "Fasted-state-specific data for the query are absent; didanosine fed-state low values are not directly applicable.",
    "Potential acid lability, first-pass metabolism, or transporter effects specific to the query are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

